/**
 * TASK: Complete WirelessRouter, the bottom of a THREE level hierarchy.
 * Device and NetworkDevice are provided -- do not edit them.
 *
 *   Device         knows a model and a wattage, and can work out a monthly
 *                  energy bill: watts * 24 * 30 / 1000 * pricePerKwh
 *   NetworkDevice  adds a port count and writes describe() as
 *                  "<model> with <ports> ports"
 *   WirelessRouter adds a radio band and must:
 *                    - pass model, watts and ports up the chain with super
 *                    - override describe() to append " on <band>", reusing the
 *                      NetworkDevice text via super.describe()
 *                    - override monthlyEnergyCost so the radio's 10 percent
 *                      overhead is added: take super's answer, multiply by 1.1
 *                      and round to 2 decimals with the inherited round2 helper
 *
 * Example: new WirelessRouter("RX-10", 12, 4, "5GHz").describe() is
 * "RX-10 with 4 ports on 5GHz", and at 0.30 per kWh its monthly cost is
 * 2.59 * 1.1 = 2.85.
 */
abstract class Device {
    private final String model;
    private final double watts;

    protected Device(String model, double watts) {
        this.model = model;
        this.watts = watts;
    }

    public String getModel() {
        return model;
    }

    public double getWatts() {
        return watts;
    }

    public abstract String describe();

    public double monthlyEnergyCost(double pricePerKwh) {
        return round2(watts * 24 * 30 / 1000.0 * pricePerKwh);
    }

    protected static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }
}

abstract class NetworkDevice extends Device {
    private final int ports;

    protected NetworkDevice(String model, double watts, int ports) {
        super(model, watts);
        this.ports = ports;
    }

    public int getPorts() {
        return ports;
    }

    @Override
    public String describe() {
        return getModel() + " with " + ports + " ports";
    }
}

public class WirelessRouter extends NetworkDevice {

    private final String band;

    public WirelessRouter(String model, double watts, int ports, String band) {
        // TODO: chain model, watts and ports up to NetworkDevice
        super("", 0, 0);
        this.band = band;
    }

    public String getBand() {
        return band;
    }

    @Override
    public String describe() {
        // TODO: the inherited description plus " on <band>"
        return "";
    }

    @Override
    public double monthlyEnergyCost(double pricePerKwh) {
        // TODO: 10 percent more than the inherited cost, rounded to 2 decimals
        return 0.0;
    }
}

