public class WirelessRouterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        WirelessRouter router = new WirelessRouter("RX-10", 12, 4, "5GHz");

        check("model reached the top of the chain", "RX-10", safe(router::getModel));
        check("watts reached the top of the chain", 12.0, round2(router::getWatts));
        check("ports stopped at the middle of the chain", 4, safe(router::getPorts));
        check("band stayed here", "5GHz", safe(router::getBand));
        check("describe extends the inherited text", "RX-10 with 4 ports on 5GHz",
                safe(router::describe));
        check("monthlyEnergyCost adds the radio overhead", 2.85,
                round2(() -> router.monthlyEnergyCost(0.30)));

        Device asDevice = router;
        check("a Device reference still runs the router version", "RX-10 with 4 ports on 5GHz",
                safe(asDevice::describe));
        check("and the overridden cost model", 2.85,
                round2(() -> asDevice.monthlyEnergyCost(0.30)));

        WirelessRouter other = new WirelessRouter("AP-2", 6, 1, "2.4GHz");
        check("a second router", "AP-2 with 1 ports on 2.4GHz", safe(other::describe));
        check("a second router cost", 1.43, round2(() -> other.monthlyEnergyCost(0.30)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

